 async function share(){
  if(!current||!valid(current.page,current.workspace)){toast('Страница ещё не загрузилась. Повторите после загрузки.',true);return false;}
  if(!canConfigureWorkspace()){toast('Общую страницу настраивает администратор пространства',true);return false;}
  const context=current,flow=beginPageDialog();if(!flow||context.ownerId!==flow.owner)return false;const {scope,host}=flow;
  if(!flow.show(`<form class="workspace-editor-shell" data-app-share-form><header><h2>Сохранить страницу как набор</h2><button type="button" class="icon-button" data-app-close aria-label="Закрыть">${icon('x')}</button></header><p>В набор войдут блоки, тексты, пункты, оформление и связи между блоками. Скрытые блоки и пункты тоже входят в набор. Схемы выбранных досок, формы, начальные значения полей и настроенные действия тоже переносятся. Личные отметки, записи и введённые числа автора не передаются. У получателя появится отдельная редактируемая копия.</p>${scope.personal?'<p>Сама страница останется личной. Набор передаёт настроенные блоки и их тексты; доступ к набору выберите ниже.</p>':''}<label>Название<input name="name" required maxlength="80" value="${e(context.page.name)}"></label><label>Описание<textarea name="description" maxlength="500" rows="3"></textarea></label><label>Доступ<select name="visibility"><option value="private">Только мне</option><option value="public">Всем пользователям платформы</option></select></label><button type="submit" class="primary">Сохранить набор</button></form>`))return false;
  $('[data-app-close]',host).onclick=flow.close;
  $('[data-app-share-form]',host).onsubmit=async event=>{
   event.preventDefault();if(!flow.owns()||flow.busy||!canConfigureWorkspace())return;const form=event.currentTarget,button=$('[type=submit]',form);button.disabled=true;flow.setBusy(true);
   try{await flow.call(`/api/workspace/pages/${context.page.id}/app/template`,{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(form)),expectedRevision:context.revision})});if(!flow.owns())return;flow.setBusy(false);toast('Набор страницы сохранён');await library();}
   catch(error){if(flow.owns())toast(error.message,true);}finally{flow.setBusy(false);button.disabled=false;}
  };return true;
 }
 async function library(){
  const flow=beginPageDialog();if(!flow)return false;const {scope,host}=flow;let items,previewSerial=0;
  try{items=await flow.call('/api/page-app/templates');}catch(error){if(flow.waiting())toast(error.message,true);return false;}
  if(!flow.show(`<div class="workspace-editor-shell"><header><div><p class="eyebrow">Наборы · ${e(scope.name)}</p><h2>Наборы страниц</h2></div><button type="button" class="icon-button" data-app-close aria-label="Закрыть">${icon('x')}</button></header><p>${scope.personal?'Добавьте готовую страницу в личное пространство. Копия будет доступна только вам.':'Установите независимую копию готовой страницы для участников этого пространства.'} Личные отметки, записи и введённые числа автора не копируются. Для списков создаются отдельные пустые доски с полями.</p><div class="app-template-list">${items.map(item=>`<article><h3>${e(item.name)}</h3><p>${e(item.description)}</p><small>${item.visibility==='private'?'Только вам':'Общий набор'}</small>${item.mine?`<button type="button" class="text-button" data-template-access="${item.id}" data-visibility="${item.visibility==='private'?'public':'private'}">${item.visibility==='private'?'Опубликовать для всех':'Снять с публикации'}</button>`:''}<button type="button" class="secondary" data-app-template="${item.id}">Посмотреть</button></article>`).join('')||'<p>Наборов страниц пока нет. Соберите страницу и сохраните её как набор.</p>'}</div></div>`))return false;
  $('[data-app-close]',host).onclick=flow.close;
  $$('[data-template-access]',host).forEach(button=>button.onclick=async()=>{
   if(!flow.owns()||flow.busy)return;button.disabled=true;flow.setBusy(true);
   try{await flow.call(`/api/page-app/templates/${button.dataset.templateAccess}`,{method:'PATCH',body:JSON.stringify({visibility:button.dataset.visibility})});if(!flow.owns())return;flow.setBusy(false);toast('Доступ обновлён; установленные копии сохранены');await library();}
   catch(error){if(flow.owns())toast(error.message,true);}finally{flow.setBusy(false);button.disabled=false;}
  });
  $$('[data-app-template]',host).forEach(button=>button.onclick=async()=>{
   if(!flow.owns()||flow.busy)return;const turn=++previewSerial;button.disabled=true;
   try{
    const item=await flow.call(`/api/page-app/templates/${button.dataset.appTemplate}`);if(!flow.owns()||turn!==previewSerial)return;
    if(!flow.show(`<div class="workspace-editor-shell"><header><div><p class="eyebrow">${scope.personal?'Личная копия':'Копия для пространства'} · ${e(scope.name)}</p><h2>${e(item.name)}</h2></div><button type="button" class="icon-button" data-app-close aria-label="Закрыть">${icon('x')}</button></header><div class="app-canvas app-template-preview">${pageAppMarkup(item.definition,{},e,true)}</div><footer class="form-actions"><button type="button" class="primary" data-app-install ${canConfigureWorkspace()?'':'disabled'}>${scope.personal?'Добавить в мои страницы':'Установить в это пространство'}</button><button type="button" class="secondary" data-app-back>Назад</button></footer>${canConfigureWorkspace()?'':'<p>Установить страницу может администратор пространства.</p>'}</div>`))return;
    applyAppStyles(host,item.definition);renderForms(host,item.definition,true);$('[data-app-close]',host).onclick=flow.close;$('[data-app-back]',host).onclick=()=>{if(flow.owns()&&!flow.busy)return library();};let installedPage=null;
    $('[data-app-install]',host).onclick=async()=>{
     if(!flow.owns()||flow.busy||!canConfigureWorkspace())return;const install=$('[data-app-install]',host);install.disabled=true;flow.setBusy(true);
     try{if(!installedPage)installedPage=await flow.call(`/api/page-app/templates/${item.id}/install`,{method:'POST',body:JSON.stringify({name:item.name})});if(!flow.owns())return;await reloadPages();if(!flow.owns())return;flow.setBusy(false);if(await flow.close()&&flow.afterClose())await navigate(`page:${installedPage.id}`);}
     catch(error){if(flow.owns())toast(error.message,true);}finally{flow.setBusy(false);install.disabled=!canConfigureWorkspace();}
    };
   }catch(error){if(flow.owns()&&turn===previewSerial)toast(error.message,true);}finally{button.disabled=false;}
  });return true;
 }
 return{render,create,edit,share,library,resetPrivate:()=>{sheetUI.reset();financeBlocks.reset?.();current=null;serial+=1;recordListState.clear();},refreshSources:()=>{if(current&&valid(current.page,current.workspace))void dataUI.mount($('#main-content'),current.definition,current);}};
